const SOUND_TIPS = {"θ":"/θ/ — глухой межзубный: кончик языка между зубами, выдыхайте без голоса (think). Не «с» и не «ф».","ð":"/ð/ — звонкий межзубный: то же положение, что для θ, но с голосом (this, mother). Не «з» и не «д».","w":"/w/ — губы трубочкой, быстро раскрыть (water). Это не «в».","æ":"/æ/ — широкое «э»: рот открыт шире, чем для русского «э» (cat, apple).","ə":"/ə/ — нейтральный безударный звук, похож на очень краткое «э» (about, teacher).","ŋ":"/ŋ/ — носовой звук: задняя часть языка к нёбу, «г» на конце не произносится (sing).","ɜː":"/ɜː/ — среднее между «ё» и «э», губы не округлять (bird, work).","r":"/r/ — язык не вибрирует, кончик загнут назад и не касается нёба (red).","h":"/h/ — лёгкий выдох, а не русское «х» (house).","ɒ":"/ɒ/ — краткое открытое «о» (hot, dog).","ʌ":"/ʌ/ — краткое «а» (cup, love)."};
